const body = $input.first().json.body || {};
const mailto = body.mailto || '';
const absender = body.absender || '';

// mailto:unsubscribe@example.com?subject=Unsubscribe
let targetEmail = '';
let subject = 'Unsubscribe';
let text = 'Unsubscribe';

try {
  const withoutPrefix = mailto.replace(/^mailto:/i, '');
  const parts = withoutPrefix.split('?');
  targetEmail = parts[0];

  if (parts[1]) {
    const query = new URLSearchParams(parts[1]);
    if (query.get('subject')) subject = query.get('subject');
    if (query.get('body')) text = query.get('body');
  }
} catch(e) {}

if (!targetEmail) {
  throw new Error('Keine gueltige E-Mail Adresse im mailto-Link gefunden');
}

return [{ json: { targetEmail, subject, text, absender } }];
